1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>AI Infra 可视化原型 v19 · 统一 3D 拓扑驾驶舱</title>
7	<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
8	<style>
9	:root{
10	  --bg:#0d1117; --panel:#161b22; --panel2:#010409; --border:#30363d; --border2:#484f58;
11	  --txt:#c9d1d9; --dim:#8b949e; --blue:#58a6ff; --dblue:#1f6feb; --purple:#a371f7;
12	  --green:#3fb950; --red:#f85149; --orange:#d29922; --teal:#39c5cf;
13	}
14	*{box-sizing:border-box;margin:0;padding:0}
15	html,body{height:100%}
16	body{background:var(--bg);color:var(--txt);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;overflow:hidden;font-size:13px}
17	#app{display:flex;flex-direction:column;height:100vh}
18	/* ===== 顶栏 ===== */
19	#topbar{height:50px;flex-shrink:0;display:flex;align-items:center;gap:10px;padding:0 14px;background:var(--panel);border-bottom:1px solid var(--border)}
20	#topbar .title{font-size:15px;font-weight:700;background:linear-gradient(90deg,var(--blue),var(--purple));-webkit-background-clip:text;background-clip:text;color:transparent;margin-right:8px;white-space:nowrap}
21	#topbar .grp{display:flex;align-items:center;gap:5px}
22	#topbar .grplab{font-size:11px;color:var(--dim);margin-right:2px}
23	button{cursor:pointer;background:#21262d;color:var(--txt);border:1px solid var(--border2);border-radius:6px;padding:4px 10px;font-size:12px;transition:.2s;white-space:nowrap}
24	button:hover{background:#30363d}
25	button.on{background:var(--dblue);border-color:var(--blue);color:#fff}
26	button.lens-TP.on{background:#0f4a50;border-color:var(--teal)}
27	button.lens-PP.on{background:#5a4310;border-color:var(--orange)}
28	button.lens-DP.on{background:#173a6b;border-color:var(--blue)}
29	button.lens-EP.on{background:#3c2a63;border-color:var(--purple)}
30	button.lens-SP.on{background:#0d4536;border-color:#2ea27a}
31	button.lens-CP.on{background:#3a2440;border-color:#c586d6}
32	button.lens-JOB.on{background:#1a3a5c;border-color:#58a6ff}
33	button.warn.on{background:#67060c;border-color:var(--red)}
34	#alertbar{display:none;margin-left:auto;background:#67060c;border:1px solid var(--red);color:#ffdcd7;border-radius:6px;padding:3px 10px;font-size:12px}
35	#alertbar.show{display:block;animation:pulse 1.4s infinite}
36	@keyframes pulse{0%,100%{opacity:1}50%{opacity:.45}}
37	/* ===== 场景剧本栏 ===== */
38	#scenbar{height:34px;flex-shrink:0;display:flex;align-items:center;gap:6px;padding:0 14px;background:#0b0f14;border-bottom:1px solid var(--border);font-size:11px;color:var(--dim)}
39	#scenbar .grplab{margin-right:4px}
40	#scenbar button{padding:3px 10px;font-size:11px}
41	#scenbar .sep{flex:1 1 auto}
42	/* ===== 主区 ===== */
43	#main{flex:1;display:flex;min-height:0}
44	/* ---- 左 ---- */
45	#left{width:430px;flex-shrink:0;border-right:1px solid var(--border);background:var(--panel2);overflow-y:auto;position:relative;padding:10px 12px 16px}
46	#lefttabs{display:flex;gap:6px;margin-bottom:10px;position:relative;z-index:6}
47	#lefttabs button{flex:1}
48	.pane{display:none}
49	.pane.show{display:block}
50	#left h3{font-size:12px;color:var(--dim);font-weight:400;margin-bottom:8px}
51	#left h3 b{color:#fff}
52	.lvrow{position:relative;border:1px solid var(--border);border-radius:8px;background:var(--panel);padding:6px 8px;cursor:pointer;transition:border-color .2s, box-shadow .2s}
53	.lvrow:hover{border-color:var(--border2)}
54	.lvrow.focus{border-color:var(--blue);box-shadow:0 0 10px rgba(88,166,255,.35)}
55	.lvrow .hd{display:flex;align-items:baseline;gap:6px}
56	.lvrow .lv{font-size:11px;font-weight:700;color:var(--blue);width:24px;flex-shrink:0}
57	.lvrow .nm{font-size:12px;color:#fff}
58	.lvrow .ct{font-size:11px;color:var(--dim);margin-left:auto;font-family:ui-monospace,monospace}
59	.lvrow .kpi{font-size:10px;color:var(--dim);margin-top:3px;font-family:ui-monospace,monospace}
60	.lvrow .kpi b{font-weight:600}
61	.lvrow.ghost{opacity:.75}
62	.lvrow .body{margin-top:5px}
63	.gap{position:relative;height:26px;display:flex;align-items:center;justify-content:flex-end;gap:6px;padding-right:4px}
64	.badge{font-size:10px;padding:1px 8px;border-radius:9px;border:1px solid var(--border2);color:var(--dim);background:#161b22;transition:.25s;position:relative;z-index:5}
65	.badge.b-TP{border-color:#1b7c86;color:#7ee0e8}
66	.badge.b-PP{border-color:#8a6416;color:#e3b341}
67	.badge.b-DP{border-color:#1f6feb;color:#9ecbff}
68	.badge.b-EP{border-color:#6e40c9;color:#d2a8ff}
69	.badge.b-ANOM{border-color:var(--red);color:#ffdcd7;display:none}
70	.badge.live{box-shadow:0 0 10px currentColor;color:#fff}
71	.badge.b-ANOM.show{display:inline-block;animation:pulse 1.2s infinite}
72	canvas.strip{display:block;width:100%;image-rendering:pixelated;border-radius:4px}
73	.inset{display:flex;gap:8px;align-items:center;margin-top:5px}
74	.inset .zoom{display:flex;gap:3px}
75	.inset .zoom i{display:block;width:16px;height:16px;border-radius:3px;border:1px solid var(--border2);background:#21262d;cursor:pointer}
76	.inset .lab{font-size:10px;color:var(--dim)}
77	.ph{display:flex;gap:6px;align-items:center}
78	.ph .die{flex:1;border:1px dashed var(--border2);border-radius:6px;padding:4px 8px;font-size:10px;color:var(--dim);text-align:center}
79	.ph .cg{border:1px solid;border-radius:4px;font-size:10px;padding:3px 8px}
80	.cg.v{border-color:var(--purple);color:#d2a8ff;background:#1c1333}
81	.cg.c{border-color:var(--red);color:#ffb3ac;background:#2d0f0e}
82	.cg.u{border-color:var(--orange);color:#e3b341;background:#2b2008}
83	#commsvg{position:absolute;top:0;left:0;pointer-events:none;z-index:4}
84	@keyframes dashmove{to{stroke-dashoffset:-22}}
85	.flow{stroke-dasharray:7 4;animation:dashmove .9s linear infinite;fill:none}
86	/* ---- 筛选栏（Smartscape 式下钻） ---- */
87	#filterbar{display:flex;align-items:center;gap:4px;flex-wrap:wrap;margin-bottom:8px;position:relative;z-index:6;background:var(--panel);border:1px solid var(--border);border-radius:8px;padding:5px 8px;font-size:11px;color:var(--dim)}
88	#filterbar b{color:#fff}
89	#filterbar button{padding:2px 7px;font-size:10.5px}
90	#topn{display:flex;gap:5px;flex-wrap:wrap;align-items:center;margin-bottom:8px;position:relative;z-index:6;font-size:10px}
91	#topn button{padding:2px 7px;font-size:10px;border-color:#6e2c2c;color:#ffb3ac}
92	#topn button.on{background:#67060c;border-color:var(--red);color:#fff}
93	/* ---- 整网映射页签 ---- */
94	#mmcv{display:block;width:100%;border-radius:4px;cursor:crosshair;border:1px solid var(--border)}
95	#mmdesc{font-size:11px;color:var(--dim);margin-top:7px;line-height:1.55;min-height:46px}
96	#mmdesc b{color:#fff}
97	#memPanel{margin-top:9px;background:var(--panel);border:1px solid var(--border);border-radius:8px;padding:8px 10px;display:none}
98	#memPanel.show{display:block}
99	#memPanel h4{font-size:11px;color:#fff;font-weight:600;margin-bottom:6px}
100	#memPanel .membar{display:flex;height:18px;border-radius:5px;overflow:hidden;border:1px solid var(--border)}
101	#memPanel .memleg{margin-top:6px;display:flex;flex-wrap:wrap;gap:4px 12px;font-size:10px;color:var(--dim)}
102	#memPanel .memleg i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px}
103	#memPanel .note{font-size:10px;color:var(--teal);margin-top:6px}
104	/* ---- 右：3D ---- */
105	#right{flex:1;position:relative;min-width:0;background:radial-gradient(ellipse at 50% 30%,#0f1626 0%,#010409 75%)}
106	#stage{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
107	#formctl{position:absolute;top:10px;right:12px;display:flex;gap:6px;z-index:5;align-items:center}
108	#formctl .hint{font-size:10px;color:var(--dim);margin-right:4px}
109	#viewlab{position:absolute;top:12px;left:14px;z-index:5;font-size:12px;color:var(--dim);pointer-events:none}
110	#viewlab b{color:#fff}
111	#probe{position:absolute;left:14px;bottom:12px;z-index:5;background:rgba(1,4,9,.85);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:11px;color:var(--dim);min-width:230px;max-width:340px;pointer-events:none}
112	#probe b{color:#fff}
113	#probe .lg{color:var(--teal);font-family:ui-monospace,monospace}
114	#hud{position:absolute;right:12px;bottom:12px;z-index:5;background:rgba(1,4,9,.85);border:1px solid var(--border);border-radius:8px;padding:8px 12px;font-size:11px;color:var(--dim);width:210px;pointer-events:none}
115	#hud .busbar{height:7px;background:#21262d;border-radius:4px;overflow:hidden;margin-top:2px}
116	#hud .busbar i{display:block;height:100%;border-radius:4px;transition:width .4s}
117	/* ===== 模式 B 抽屉 ===== */
118	#drawer{display:none;height:248px;flex-shrink:0;background:var(--panel2);border-top:1px solid var(--border);flex-direction:column;padding:8px 14px 10px}
119	#drawer.show{display:flex}
120	#drawer .drhead{display:flex;align-items:center;gap:6px;margin-bottom:6px}
121	#drawer .drtitle{font-size:12px;color:var(--orange);font-weight:600;margin-right:8px}
122	#drawer canvas{flex:1;width:100%;min-height:0;border:1px solid var(--border);border-radius:6px;background:var(--panel2)}
123	/* ===== 底部时间轴 ===== */
124	#footer{height:58px;flex-shrink:0;display:flex;align-items:center;gap:12px;padding:0 14px;background:var(--panel);border-top:1px solid var(--border)}
125	#phasetrack{flex:1;display:flex;height:26px;border-radius:6px;overflow:hidden;position:relative;cursor:pointer}
126	.pseg{flex:1;display:flex;align-items:center;justify-content:center;font-size:11px;color:#fff;opacity:.35;transition:opacity .3s;border-right:1px solid #0d1117}
127	.pseg.on{opacity:1}
128	.pseg.s-TP{background:#0f4a50}.pseg.s-PP{background:#5a4310}.pseg.s-EP{background:#3c2a63}.pseg.s-DP{background:#173a6b}
129	#playhead{position:absolute;top:-4px;bottom:-4px;width:2px;background:#fff;box-shadow:0 0 8px #fff;pointer-events:none}
130	#phaselab{font-size:12px;color:var(--orange);width:210px;text-align:right}
131	</style>
132	</head>
133	<body>
134	<div id="app">
135	  <div id="topbar">
136	    <span class="title">AI Infra 统一驾驶舱 v19</span>
137	    <span class="grp"><span class="grplab">策略透镜</span>
138	      <button class="lensbtn on" data-lens="NONE">无·健康度</button>
139	      <button class="lensbtn lens-TP" data-lens="TP">TP×8</button>
140	      <button class="lensbtn lens-PP" data-lens="PP">PP×16</button>
141	      <button class="lensbtn lens-DP" data-lens="DP">DP×64</button>
142	      <button class="lensbtn lens-EP" data-lens="EP">EP·MoE</button>
143	      <button class="lensbtn lens-SP" data-lens="SP">SP·序列</button>
144	      <button class="lensbtn lens-CP" data-lens="CP">CP·上下文</button>
145	      <button class="lensbtn lens-JOB" data-lens="JOB">任务·部署</button>
146	    </span>
147	    <span class="grp"><span class="grplab">场景</span>
148	      <button id="btnAnom" class="warn">注入 EP 跨超节点异常</button>
149	      <button id="btnModeB">模式B·泳道回放</button>
150	      <button id="btnScatter" style="display:none">散射跨域路由</button>
151	    </span>
152	    <span class="grp" style="margin-left:6px"><canvas id="sparks" width="340" height="36" style="width:255px;height:27px"></canvas></span>
153	    <span id="alertbar">⚠ EP AllToAll 越界：8 个专家组成员被越区调度至相邻超节点，跨 Pod 光链路拥塞</span>
154	  </div>
155	  <div id="scenbar">
156	    <span class="grplab">场景剧本 · 按任务一键编排全部视图</span>
157	    <button id="scPatrol">🩺 巡检大盘</button>
158	    <button id="scMoe">🚨 MoE 越界诊断</button>
159	    <button id="scSlow">🐢 找慢 DP 副本</button>
160	    <button id="scDeep">🔬 单机深潜</button>
161	    <button id="scDeploy">📦 部署审视</button>
162	    <span class="grplab" style="margin-left:14px">连线镜头</span>
163	    <button class="wirebtn on" data-wire="AUTO">自动·随阶段</button>
164	    <button class="wirebtn" data-wire="COMM">通信域</button>
165	    <button class="wirebtn" data-wire="FLOW">互联流量</button>
166	    <button class="wirebtn" data-wire="LINK">物理链路</button>
167	    <button class="wirebtn" data-wire="PATH">消息路径·PXN</button>
168	    <span class="sep"></span>
169	    <button id="scReset">⟲ 重置视图</button>
170	  </div>
171	  <div id="main">
172	    <div id="left">
173	      <svg id="commsvg"></svg>
174	      <div id="lefttabs">
175	        <button id="tabHier" class="on">层级剖面 L7→L0</button>
176	        <button id="tabModel">整网分隔映射</button>
177	      </div>
178	      <!-- ============ 页签 1：物理层级剖面 ============ -->
179	      <div class="pane show" id="paneHier">
180	      <h3><b>2D 层级剖面</b> · 点击实体下钻筛选（Smartscape 式）</h3>
181	      <div id="filterbar">
182	        <span id="fbCrumb">未筛选：点击任意 Host / 3D 方块下钻</span>
183	        <span style="flex:1 1 auto"></span>
184	        <button class="relbtn on" data-rel="AUTO">跟随阶段</button>
185	        <button class="relbtn lens-TP" data-rel="TP">TP组</button>
186	        <button class="relbtn lens-PP" data-rel="PP">PP链</button>
187	        <button class="relbtn lens-DP" data-rel="DP">DP环</button>
188	        <button class="relbtn lens-EP" data-rel="EP">EP对端</button>
189	        <button id="fbClear">✕ 清除</button>
190	      </div>
191	      <div id="topn"></div>
192	      <div class="lvrow ghost" data-level="L7"><div class="hd"><span class="lv">L7</span><span class="nm">Global</span><span class="ct">全球调度域 · 缩略</span></div></div>
193	      <div class="gap" data-gap="L7L6"></div>
194	      <div class="lvrow ghost" data-level="L6"><div class="hd"><span class="lv">L6</span><span class="nm">Cluster · SuperCluster</span><span class="ct" id="ctL6">×64 超节点 · 缩略</span></div><div class="kpi" id="kpiL6"></div>
195	        <div class="body" id="l6body"></div></div>
196	      <div class="gap" data-gap="L6L5"></div>
197	      <div class="lvrow ghost" data-level="L5"><div class="hd"><span class="lv">L5</span><span class="nm">Service Pool · 服务池（组）</span><span class="ct" id="ctL5">本池 8 超节点 · 缩略</span></div><div class="kpi" id="kpiL5"></div>
198	        <div class="body" id="l5body"></div></div>
199	      <div class="gap" data-gap="L5L4">
200	        <span class="badge b-ANOM" id="bdAnom">EP·AllToAll 越界 ↑</span>

200	        <span class="badge b-ANOM" id="bdAnom">EP·AllToAll 越界 ↑</span>
201	        <span class="badge b-DP" id="bdDPx">DP·跨超节点同步(多Pod作业)</span>
202	      </div>
203	      <div class="lvrow focus" data-level="L4"><div class="hd"><span class="lv">L4</span><span class="nm">Pod · Atlas 950 超节点（=SN0，池内成员之一）</span><span class="ct">8192 NPU · UB 16PB/s</span></div><div class="kpi" id="kpiL4"></div>
204	        <div class="body" id="l4body"></div></div>
205	      <div class="gap" data-gap="L4L3">
206	        <span class="badge b-PP" id="bdPP">PP·接力 ×16 段</span>
207	        <span class="badge b-DP" id="bdDP">DP·梯度同步 ×64 副本</span>
208	        <span class="badge b-EP" id="bdEP">EP·AllToAll 浪涌</span>
209	      </div>
210	      <div class="lvrow" data-level="L3"><div class="hd"><span class="lv">L3</span><span class="nm">Host · 计算节点</span><span class="ct" id="ctL3">×1024 · 每节点 8 NPU</span></div><div class="kpi" id="kpiL3"></div>
211	        <div class="body"><canvas class="strip" id="cvL3" width="404" height="104"></canvas></div></div>
212	      <div class="gap" data-gap="L3L2">
213	        <span class="badge b-TP" id="bdTP">TP·AllReduce ×8 · 节点内 UB</span>
214	      </div>
215	      <div class="lvrow" data-level="L2"><div class="hd"><span class="lv">L2</span><span class="nm">Chip · NPU 昇腾950DT</span><span class="ct" id="ctL2">×8192</span></div><div class="kpi" id="kpiL2"></div>
216	        <div class="body">
217	          <canvas class="strip" id="cvL2" width="404" height="112"></canvas>
218	          <div class="inset"><span class="lab">焦点 Host 放大 ×8：</span><span class="zoom" id="chipZoom"></span></div>
219	        </div></div>
220	      <div class="gap" data-gap="L2L1"></div>
221	      <div class="lvrow ghost" data-level="L1"><div class="hd"><span class="lv">L1</span><span class="nm">Die（可选）</span><span class="ct">结构占位 · 950DT 未公开</span></div>
222	        <div class="body ph"><span class="die">Die 0 · 占位</span><span class="die">Die 1 · 占位</span></div></div>
223	      <div class="gap" data-gap="L1L0"></div>
224	      <div class="lvrow ghost" data-level="L0"><div class="hd"><span class="lv">L0</span><span class="nm">Core-Group</span><span class="ct">结构占位</span></div>
225	        <div class="body ph"><span class="cg v">V · Vector</span><span class="cg c">C · Cube</span><span class="cg u">CPU · 调度</span></div></div>
226	      </div>
227	      <!-- ============ 页签 2：整网分隔映射（v2 第十组件融合） ============ -->
228	      <div class="pane" id="paneModel">
229	        <h3><b>模型侧 · 整网分隔映射</b>（拼图原图 ⇄ 3D 货架 双向索引）<br>
230	        行=整网 48 层（<b>Pangu Pro MoE 72B-A16B</b> · arXiv:2505.21411）· 列=一个 DP 副本 128 芯片（PP16×TP8）· 每层含 64 路由专家(8 组·MoGE)+4 共享</h3>
231	        <div style="display:flex;gap:6px;margin-bottom:8px">
232	          <button id="btnDPring" class="on">DP×64 整网复制 · 外圈</button>
233	          <button id="btnClearSel">清除选择</button>
234	        </div>
235	        <canvas id="mmcv" width="404" height="400"></canvas>
236	        <div id="mmdesc">点<b>行</b>=整网的一层 → 右侧 3D 亮起承载它的卡（含全部 64 个 DP 副本；魔方形态下是一整个水平切片）。点<b>格/列</b>=一张卡 → 反查它装了整网哪些片 + 显存构成。TP/PP/EP=真·裁切整网（紫色裁切线）；DP 不切、是整网复制（绿色虚线外圈）。</div>
237	        <div id="memPanel"></div>
238	      </div>
239	    </div>
240	    <div id="right">
241	      <canvas id="stage"></canvas>
242	      <div id="formctl">
243	        <span class="hint">拖拽旋转 · 滚轮缩放 · 选层=相机飞行 · Host 侧条=显存水位</span>
244	        <button id="btnPhys" class="on">物理层级形态</button>
245	        <button id="btnCube">逻辑魔方形态</button>
246	        <button id="btnStack">层级堆叠形态</button>
247	        <span id="cubeModes" style="display:none;gap:5px">
248	          <button id="cm0" class="on">标准</button>
249	          <button id="cm1">DP平铺</button>
250	          <button id="cm2">EP聚簇</button>
251	          <button id="cm3">TP切片</button>
252	          <button id="cm4">PP流水</button>
253	        </span>
254	      </div>
255	      <div id="viewlab"></div>
256	      <div id="probe"></div>
257	      <div id="hud"></div>
258	    </div>
259	  </div>
260	  <div id="drawer">
