300	  { id:'PP', name:'PP · 阶段接力 Send/Recv', bus:'Pod 内跨节点 UB · 中频', load:.45 },
301	  { id:'EP', name:'EP · MoE AllToAll 浪涌', bus:'Pod 内全互联 · 浪涌', load:.88 },
302	  { id:'DP', name:'DP · 梯度 AllReduce', bus:'Pod 内 + 跨 Pod(多作业) · 低频大包', load:.60 },
303	];
304	const S = {
305	  lens:'NONE', form:'phys', morph:0,
306	  level:'L4', focusHost:137, focusChip:137*8+3,
307	  phase:0, t:0, playing:false, anomaly:false,
308	  hoverHost:-1, hoverSide:'',
309	  tab:'hier',
