313	const rng = (i)=>{ let x = Math.sin(i*127.1+311.7)*43758.5453; return x-Math.floor(x); };
314	const health = new Float32Array(N_HOST);
315	for(let h=0;h<N_HOST;h++){ health[h] = .25 + .5*rng(h); }
316	[311,312,313,570,571].forEach(h=>health[h]=.97);
317	const expertHosts = []; for(let e=0;e<N_EXP;e++) expertHosts.push((e*16+5)%N_HOST);
318	const hotExperts = new Set([5,21]);            // 对照示意：传统 Top-K 的热点（MoGE 本身 IS=0，最热≈12.5%）
319	const anomExperts = [3,11,19,27,35,43,51,59];  // 每组 1 个成员被越区调度（异常注入场景）
320	const isExpertHost = new Int8Array(N_HOST);
