322	const isAnomHost = new Int8Array(N_HOST);
323	anomExperts.forEach(e=>{ isAnomHost[expertHosts[e]]=1; });
324	const hostExpertIdx = new Int16Array(N_HOST).fill(-1);
325	expertHosts.forEach((h,e)=>{ hostExpertIdx[h]=e; });
326	/* 任务/作业部署（框架 → 物理映射）：哪些机器部署了哪些计算任务 */
