328	const JOBS = [
329	  { name:'训练 · Pangu Pro MoE 72B-A16B', fw:'MindSpeed + CANN · 13T tokens · TP8/EP2/PP5' },
330	  { name:'推理 · Pangu Pro MoE W8A8', fw:'MindIE · 1148 tok/s/卡@100ms（MTP 1528）' },
331	  { name:'空闲 / 维护', fw:'—' } ];
332	const memLevel = new Float32Array(N_HOST);
