376	    const k = .75 + .35*(s/7); return `rgb(${base[0]*k|0},${base[1]*k|0},${base[2]*k|0})`; }
377	  if(S.lens==='SP'){ const k = .7 + .4*(s/7);
378	    return `rgb(${30*k|0},${122*k|0},${90*k|0})`; }
379	  return baseHostColor(h);
380	}
381	/* ============ 当前阶段的参与者（左侧弧线 / 画布描边 / 3D 通信线共用） ============ */
382	function phaseSets(){
383	  const ph = PHASES[S.phase].id;
384	  const dpF = dpOf(S.focusHost), ppF = ppOf(S.focusHost);
385	  if(ph==='TP') return { hosts:[S.focusHost],
386	    desc:`Host ${S.focusHost} 内 8×NPU 环状 AllReduce（节点内 UB）` };
387	  if(ph==='PP'){ const hs=[]; for(let k=0;k<16;k++) hs.push(dpF*16+k);
388	    return { hosts:hs, chain:true, desc:`DP 副本 ${dpF}：Stage0 → … → Stage15 逐段接力` }; }
389	  if(ph==='EP'){ const hub = expertHosts[5], hs=[hub];
390	    for(let e=1;e<N_EXP;e+=5){ const h=expertHosts[e]; if(h!==hub) hs.push(h); }
391	    return { hosts:hs, hub, desc:`热点专家 Host ${hub} ⇄ 各专家 Host · AllToAll 双向` }; }
392	  const hs=[]; for(let d=0;d<64;d+=8) hs.push(d*16+ppF);
393	  return { hosts:hs, ring:true, desc:`PP Stage${ppF} 的 DP 梯度环（示 8/64 副本）` };
394	}
395	/* ============ Smartscape 式筛选下钻：点实体 → 关联集合 → 各层折叠 ============ */
396	function activeRel(){ return S.rel==='AUTO' ? PHASES[S.phase].id : S.rel; }
397	function relSet(h){
398	  const r = activeRel();
399	  if(r==='TP') return { hosts:[h], color:COL.TP, label:`TP 组：Host ${h} 节点内 8×NPU` };
400	  if(r==='PP'){ const dp=dpOf(h), hs=[]; for(let k=0;k<16;k++) hs.push(dp*16+k);
401	    return { hosts:hs, color:COL.PP, label:`PP 链：DP 副本 ${dp} 的 16 段接力` }; }
402	  if(r==='DP'){ const pp=ppOf(h), hs=[]; for(let d=0;d<64;d++) hs.push(d*16+pp);
403	    return { hosts:hs, color:COL.DP, label:`DP 环：Stage${pp} 的 64 个同位副本` }; }
404	  if(!isExpertHost[h]) return { hosts:[h], color:COL.EP, label:`Host ${h} 非专家节点，无 EP 对端`, empty:true };
405	  const hs=[h]; for(let e=0;e<N_EXP;e+=3){ const x=expertHosts[e]; if(x!==h&&hs.indexOf(x)<0) hs.push(x); }
406	  return { hosts:hs, color:COL.EP, label:`EP 对端：专家互联（示 ${hs.length-1} 个）` };
407	}
408	let relCache = null;
409	function invalidateRel(){ relCache = null; }
410	function filterInfo(){
