412	  if(!relCache){ relCache = relSet(S.filterHost);
413	    relCache.set = new Set(relCache.hosts); relCache.set.add(S.filterHost); }
414	  return relCache;
415	}
416	function filterPassHost(h){ const f = filterInfo(); return !f || f.set.has(h); }
417	function setFilter(h){
418	  if(S.filterHost===h){ S.filterHost=null; }
419	  else { S.filterHost=h; S.focusHost=h; S.focusChip=h*8; }

