}
function updateLevelKPI(){
  let sum=0, red=0, peak=0;
  for(let h=0;h<N_HOST;h++){ const u = 40+health[h]*55;
    sum+=u; if(u>peak) peak=u;
    if(health[h]>.95 || (S.anomaly&&isAnomHost[h])) red++; }
  const typ=(sum/N_HOST)|0, redP=(red/N_HOST*100).toFixed(1);
  const html = `典型 <b style="color:#c9d1d9">${typ}%</b> · 红 <b style="color:${red>5?'#f85149':'#8b949e'}">${redP}%</b> · 峰 <b style="color:#e3b341">${peak|0}%</b>`;
  ['kpiL6','kpiL5','kpiL4','kpiL3','kpiL2'].forEach(id=>{
