function updateIndicators(){
  const wC = ease(Wgt.cube), wS = Wgt.stack, wP = Wgt.phys;
  const sum = wP+wC+wS||1, nP=wP/sum, nC=wC/sum, nS=wS/sum;
  const bl = (fP,fC,fS)=>fP*nP+fC*nC+fS*nS;
  if(S.hoverHost>=0 && nC<0.5){ const a = nP/((nP+nS)||1);
    hoverBox.visible=true;
    hostPos(S.hoverHost,vA).multiplyScalar(a);
    vA.addScaledVector(hostStack(S.hoverHost,vB), 1-a);
    hoverBox.position.copy(vA);
    hoverBox.scale.set(.7+.65*a, .32+.23*a, .7+.5*a); }
  else hoverBox.visible=false;
  // 焦点 Host：物理托盘 / 魔方 TP 行 / 堆叠瓦片
  hostPos(S.focusHost,vA).multiplyScalar(nP);
  chipCube(S.focusHost*8,vB); const rowC = vB.clone(); chipCube(S.focusHost*8+7,vB); rowC.lerp(vB,.5);
  vA.addScaledVector(rowC,nC).addScaledVector(hostStack(S.focusHost,vB),nS);
  focusHostBox.position.copy(vA);
  focusHostBox.scale.set(bl(1.35,12.6,.7), bl(.55,1.3,.32), bl(1.2,1.3,.7));
  // 焦点芯片
  chipPhys(S.focusChip,vA).multiplyScalar(nP);
  vA.addScaledVector(chipCube(S.focusChip,vB),nC).addScaledVector(chipStack(S.focusChip,vB),nS);
  focusChipBox.position.copy(vA);
  focusChipBox.scale.set(bl(.26,1.2,.3), bl(.2,.9,.26), bl(.34,.7,.36));
  // L1/L0 下钻细节（仅物理形态）
  detail.visible = (S.level==='L1'||S.level==='L0') && nP>0.7;
  if(detail.visible){ chipPhys(S.focusChip,vA); detail.position.copy(vA); }
  // 深下钻时机柜淡化 → 用焦点机柜线框保留空间参照
  const cabLv = S.level==='L3'||S.level==='L2'||S.level==='L1'||S.level==='L0';
  focusCabBox.visible = cabLv && nP>0.5;
  if(focusCabBox.visible){ const cab = cabOf(S.focusHost);
    focusCabBox.position.set((cab%16-7.5)*1.8, 1.85, ((cab>>4)-3.5)*2.4);
    focusCabBox.scale.set(1.5,3.72,1.28); }
  const showFocus = cabLv && nP>0.5;
  focusHostMesh.visible = focusChipsMesh.visible = showFocus;
  if(showFocus){
    hostPos(S.focusHost, focusHostMesh.position);
    focusHostMesh.material.color.setStyle(hostColor(S.focusHost));
    for(let s2=0;s2<8;s2++){ chipPhys(S.focusHost*8+s2, vA);
      dummy.position.copy(vA); dummy.rotation.set(0,0,0); dummy.scale.set(1,1,1); dummy.updateMatrix();
      focusChipsMesh.setMatrixAt(s2, dummy.matrix);
      focusChipsMesh.setColorAt(s2, cTmp.setStyle(chipColor(S.focusHost*8+s2))); }
    focusChipsMesh.instanceMatrix.needsUpdate = true;
    focusChipsMesh.instanceColor.needsUpdate = true;
  }
  // 堆叠形态：焦点垂链 L7→L0
  if(stackPath){ stackPath.visible = nS>0.05;
    if(stackPath.visible){ const P = stackPath.geometry.attributes.position;
      const pts = [[0,STACK.L7,0],[-5.95,STACK.L6,-5.95],[-8.75,STACK.L5,0],[0,STACK.L4,0]];
      hostStack(S.focusHost,vA); pts.push([vA.x,vA.y,vA.z]);
      chipStack(S.focusChip,vA); pts.push([vA.x,vA.y,vA.z]);
      pts.push([0,STACK.L1,0],[0,STACK.L0,0]);
      pts.forEach((p,i)=>P.setXYZ(i,p[0],p[1],p[2])); P.needsUpdate = true; } }
  // 层级选中反馈：堆叠平台描边高亮 / 物理形态边界高亮
  if(nS>0.02){ for(const lv in stackPlats){ const sel = S.level===lv, o = stackPlats[lv];
      o.edges.material.color.set(sel?0x58a6ff:0x30363d);
      o.edges.material.opacity = (sel?1:.4)*Wgt.stack;
      o.label.material.color.set(sel?0xffffff:0x8b949e); } }
  if(poolLine){ poolLine.material.color.set(S.level==='L5'?0x9ecbff:0x58a6ff);
    poolLine.material.opacity = (S.level==='L5'?1:.5)*Wgt.phys; }
  if(podBaseEdges){ podBaseEdges.material.color.set(S.level==='L4'?0x58a6ff:0x1f6feb);
    podBaseEdges.material.opacity = (S.level==='L4'?1:.75)*Wgt.phys; }
}
function updateCommPulse(now){
  const k = S.playing ? .45+.55*Math.abs(Math.sin(now/260)) : .8;
  commGroup.children.forEach(o=>{ o.material.opacity = o.material.userData.base*k; });
  cubeComm.children.forEach(o=>{ o.material.opacity = o.material.userData.base*k; });
}
/* ---- 相机：单一视角 + 层级驱动飞行缩放 ---- */
let yaw = .82, pitch = .58, zoomBias = 1;
const camCur = { t:V3(0,2,0), d:52 };
function camGoal(){
  if(S.form==='cube' || Wgt.cube>0.5){
    if(cubeMode===1) return { t:V3(0,10,0), d:150 };
    if(cubeMode===2) return { t:V3(0,16,0), d:95 };
    if(cubeMode===3) return { t:V3(0,17,0), d:118 };
    if(cubeMode===4) return { t:V3(0,12,0), d:152 };
    return { t:V3(CUBE.cx,CUBE.cy,CUBE.cz), d:82 }; }
  if(S.form==='stack' || Wgt.stack>0.5){
    const ST = { L7:[15,58], L6:[STACK.L6,32], L5:[STACK.L5,26], L4:[STACK.L4,18],
