}
function laneHost(){ return S.filterHost!=null ? S.filterHost : S.focusHost; }
function fitCanvas(cv){ const dpr = Math.min(window.devicePixelRatio||1, 2);
  const w = cv.clientWidth||1000, h = cv.clientHeight||200;
  if(cv.width !== (w*dpr|0) || cv.height !== (h*dpr|0)){ cv.width = w*dpr|0; cv.height = h*dpr|0; }
  const c = cv.getContext('2d'); c.setTransform(dpr,0,0,dpr,0,0); c.clearRect(0,0,w,h);
  return { c, W:w, H:h };
}
function laneLayout(Hh){                      // 确定性伪 Trace：随 Host / 模式 / 异常变化
  const exp = !!isExpertHost[Hh];
  const hotSet = laneMode==='moge' ? [] : (exp? [1,3,6] : [2,5]);
  const cyc=[]; let total=0;
  for(let b=0;b<5;b++){ let mx=0; const row=[], cm=[];
    for(let r=0;r<8;r++){ const hot=hotSet.includes(r);
      const L = laneMode==='moge' ? 88+rng(Hh+b)*8
        : (hot? 112+rng(Hh*31+r*7+b*13)*44 : 52+rng(Hh*17+r*11+b*5)*34);
      const CL = (laneMode==='moge'?20:26) + rng(Hh*7+r*3+b*11)*(laneMode==='moge'?6:16);
      row.push(L); cm.push(CL); mx=Math.max(mx,L); }
    const anomX = (S.anomaly && laneMode==='topk' && b===2) ? (isAnomHost[Hh]?34:14) : 0;
    cyc.push({row,cm,mx,anomX,start:total});
    total += mx + Math.max(...cm) + anomX; }
  return {cyc,total,hotSet,exp};
}
function renderLane(){
  const {c,W,H} = fitCanvas($('#cvLane'));
  const Hh = laneHost();
  const {cyc,total,hotSet,exp} = laneLayout(Hh);
  const x0=64, w=W-x0-16, top=15;
  const laneH = H-104, rowH = laneH/8, cY = top+laneH+6;
  const u = w/total;
  const tx = x0 + Math.min(1,Math.max(0,S.t))*w;
  c.font='9px ui-monospace,monospace';
  for(let t=0;t<=7;t++){ const x=x0+t*w/7;
    c.fillStyle='#1b212b'; c.fillRect(x,top-4,1,cY+40-top);
    c.fillStyle='#6e7681'; c.textAlign='left'; c.fillText((t*50)+'μs', x+2, 9); }
  const seg=(x,y,ww,hh,col)=>{ c.globalAlpha=(x+ww<=tx)?1:(x<tx?.9:.26);
    c.fillStyle=col; c.fillRect(x,y,Math.max(ww,1),hh); c.globalAlpha=1; };
  for(let r=0;r<8;r++){
    const yC=top+r*rowH, yM=yC+rowH*.46, bh=Math.max(4,rowH*.34);
    c.fillStyle=hotSet.includes(r)?'#e3b341':'#8b949e'; c.textAlign='right';
    c.fillText('TP'+r, x0-6, yC+bh);
    for(const cy of cyc){
      const s=x0+cy.start*u, L=cy.row[r], CL=cy.cm[r];
      seg(s,yC,L*u,bh,'#1f6feb');
      if(L<cy.mx-1) seg(s+L*u,yC,(cy.mx-L)*u,bh,'rgba(248,81,73,.6)');
      seg(s+cy.mx*u,yM,CL*u,bh, laneMode==='moge'?'#2ea043':'#a371f7');
      if(cy.anomX) seg(s+(cy.mx+CL)*u,yM,cy.anomX*u,bh,'rgba(248,81,73,.95)');
    } }
  // —— 硬件计数器轨：与软件泳道同轴（Perfetto counter track / Vampir Performance Radar 范式）——
  const NB=160, busy=new Float32Array(NB), bw2=new Float32Array(NB);
  for(let r=0;r<8;r++) for(const cy of cyc){
    const a1=(cy.start/total*NB)|0, b1=Math.min(NB-1,((cy.start+cy.row[r])/total*NB)|0);
    for(let i=a1;i<=b1;i++) busy[i]+=1/8;
    const c0=((cy.start+cy.mx)/total*NB)|0,
          c1=Math.min(NB-1,((cy.start+cy.mx+cy.cm[r]+cy.anomX)/total*NB)|0);
    for(let i=c0;i<=c1;i++) bw2[i]+=1/8; }
  const track=(data,y,h2,col,label)=>{
    c.font='9px ui-monospace,monospace';
    c.fillStyle='#8b949e'; c.textAlign='right'; c.fillText(label, x0-6, y+h2-3);
    c.strokeStyle='#1b212b'; c.strokeRect(x0,y,w,h2);
    c.fillStyle=col; c.beginPath(); c.moveTo(x0,y+h2);
    for(let i=0;i<NB;i++) c.lineTo(x0+(i+.5)/NB*w, y+h2-data[i]*h2*.94);
    c.lineTo(x0+w,y+h2); c.closePath(); c.globalAlpha=.45; c.fill(); c.globalAlpha=1; };
  track(busy, cY, 17, '#3fb950', 'Cube利用率');
  track(bw2, cY+21, 17, '#a371f7', 'UB带宽');
  c.strokeStyle='#fff'; c.lineWidth=1;
  c.beginPath(); c.moveTo(tx,top-6); c.lineTo(tx,cY+38); c.stroke();
  c.fillStyle='#fff'; c.textAlign='center'; c.font='9px ui-monospace,monospace';
  c.fillText('▶ '+PHASES[S.phase].id+' · '+((S.t*350)|0)+'μs', Math.min(W-60,Math.max(x0+40,tx)), cY+48);
  c.textAlign='left'; c.font='10px sans-serif';
  c.fillStyle = laneMode==='moge' ? '#3fb950' : '#f85149';
  c.fillText(laneMode==='moge'
    ? `Host ${Hh} · MoGE 均衡：Compute 齐整 · AllToAll 全掩盖 · IS=0（组内 top-1 强制均衡 · 最热专家≈12.5%）`
    : `Host ${Hh}${exp?'（MoE 专家节点）':''} · Top-K：热点 ${hotSet.map(r=>'TP'+r).join('/')} 拖长 → Bubble 处利用率轨同步塌陷（对照：Top-K 最热专家可占 30% token）${S.anomaly?' · 第3周期跨超节点加时':''}`,
    x0, H-4);
  const lg=[['#1f6feb','Compute'],['#a371f7','AllToAll'],['rgba(248,81,73,.7)','Bubble/越界'],['#3fb950','下方=硬件计数器(同轴)']];
  let lx=Math.max(x0+440, W-480); c.font='9px sans-serif';
  lg.forEach(g2=>{ c.fillStyle=g2[0]; c.fillRect(lx,H-12,10,7);
    c.fillStyle='#8b949e'; c.fillText(g2[1], lx+13, H-5); lx+=c.measureText(g2[1]).width+26; });
}
$('#cvLane').addEventListener('click', ev=>{
  const r = $('#cvLane').getBoundingClientRect();
  const x0=64, w=r.width-x0-16, x=ev.clientX-r.left;
  S.t = Math.min(.999, Math.max(0, (x-x0)/w)); syncPhase(); renderLane(); });
function renderBw(){
  const {c,W,H} = fitCanvas($('#cvBw'));
  const x0=60, y0=H-28, w=W-x0-30, h=H-54;
  const X=k=>x0+(k-9)/(34-9)*w, Y=v=>y0-v/210*h;
  c.strokeStyle='#30363d'; c.strokeRect(x0,y0-h,w,h);
  c.font='9px ui-monospace,monospace'; c.textAlign='center';
  [['512B',9],['16KB',14],['512KB',19],['16MB',24],['512MB',29],['16GB',34]].forEach(t2=>{
    c.fillStyle='#21262d'; c.fillRect(X(t2[1]),y0-h,1,h);
    c.fillStyle='#6e7681'; c.fillText(t2[0], X(t2[1]), y0+12); });
  c.textAlign='right'; [0,50,100,150,195].forEach(v=>{ c.fillStyle='#6e7681'; c.fillText(v, x0-4, Y(v)+3); });
  const base = k=>195/(1+Math.exp(-(k-17)/2.6));
  c.fillStyle='rgba(139,148,158,.14)'; c.beginPath();
  for(let k=9;k<=34;k+=.5){ const y=Y(base(k)*1.08); k===9?c.moveTo(X(k),y):c.lineTo(X(k),y); }
  for(let k=34;k>=9;k-=.5) c.lineTo(X(k),Y(base(k)*.92));
  c.closePath(); c.fill();
  c.strokeStyle = S.anomaly?'#f85149':'#39c5cf'; c.lineWidth=1.8; c.beginPath();
  for(let k=9;k<=34;k+=.5){
    let v = base(k)*.97;
    if(S.anomaly && k>27) v = base(27)*.97*Math.max(.52, 1-(k-27)*.12);
    const y=Y(v); k===9?c.moveTo(X(k),y):c.lineTo(X(k),y); }
  c.stroke();
  c.textAlign='left'; c.font='10px sans-serif';
  if(S.anomaly){ c.fillStyle='#f85149';
    c.fillText('峰值(≈256MB)后回落 → 大象流哈希不均 / 跨Pod拥塞指纹 · 自动告警', X(24.5), Y(base(27))-12); }
  else { c.fillStyle='#39c5cf'; c.fillText('平台区贴合直连基线 ≈195GB/s · 健康', X(27), Y(195)+16); }
  c.fillStyle='#8b949e';
  c.fillText('busbw–消息大小基线（类 nccl-tests/hccl_test 常态化采集 · 灰带=历史基线±8% · 判读看峰值与平台区）', x0+4, y0-h+14);
}
let mxHover = null;
function renderMx(){
  const {c,W,H} = fitCanvas($('#cvMx'));
  const N=8, cs=Math.max(12,Math.min((H-52)/N, 20)), x0=110, y0=28;
  const hotG = new Set([...hotExperts].map(e=>e>>3));
  const anomG = new Set(anomExperts.map(e=>e>>3));
  let vmax=0; const vol=[];
  for(let i=0;i<N;i++){ vol.push([]);
    for(let j=0;j<N;j++){ let v = i===j? 0 : .15+rng(i*8+j)*.5;
      if(hotG.has(j)) v*=2.6; if(hotG.has(i)) v*=1.4;
      vol[i][j]=v; if(v>vmax) vmax=v; } }
  for(let i=0;i<N;i++) for(let j=0;j<N;j++){
    const v = vol[i][j]/vmax;
    c.fillStyle = i===j? '#10141b' : (v>.8? `rgba(248,113,73,${.5+v*.45})` : `rgba(88,166,255,${.08+v*.8})`);
    c.fillRect(x0+j*cs, y0+i*cs, cs-1, cs-1);
    if(S.anomaly && anomG.has(i)){ c.strokeStyle='rgba(248,81,73,.85)';
      c.strokeRect(x0+j*cs+.5, y0+i*cs+.5, cs-2, cs-2); } }
  c.font='8px ui-monospace,monospace'; c.fillStyle='#6e7681';
  for(let i=0;i<N;i++){ c.textAlign='right'; c.fillText('G'+i, x0-3, y0+i*cs+cs*.7);
    c.textAlign='center'; c.fillText('G'+i, x0+i*cs+cs/2, y0-4); }
  const ix = x0+N*cs+18;
  c.textAlign='left'; c.font='10px sans-serif'; c.fillStyle='#c9d1d9';
  c.fillText('EP AllToAll 消息矩阵 · Pangu Pro MoE 8 组（Vampir/Paraver 范式）', ix, y0+8);
  c.fillStyle='#8b949e';
  c.fillText('行=源专家组 · 列=目的组 · 亮度=消息量 · 对角线=组内不跨卡', ix, y0+24);
  c.fillText('橙红竖条=热点组被路由打爆（各源都在给它发）→ 负载失衡指纹', ix, y0+40);
  if(S.anomaly){ c.fillStyle='#f85149';
    c.fillText('红框行=含越界专家的组：这些流量实际落在跨 Pod 光链路（理论应为 0）', ix, y0+58); }
  if(mxHover){ const {i,j}=mxHover; c.fillStyle='#e6edf3';
    c.fillText(`G${i} → G${j}：${(vol[i][j]*37).toFixed(1)} GB/step${hotG.has(j)?' · 目的=热点组⚠':''}`, ix, y0+78); }
}
$('#cvMx').addEventListener('mousemove', ev=>{
  const r = $('#cvMx').getBoundingClientRect();
  const cs = Math.max(12,Math.min((r.height-52)/8, 20));
  const i = ((ev.clientY-r.top-28)/cs)|0, j = ((ev.clientX-r.left-110)/cs)|0;
  const nh = (i>=0&&i<8&&j>=0&&j<8&&i!==j)? {i,j} : null;
  if(JSON.stringify(nh)!==JSON.stringify(mxHover)){ mxHover=nh; renderMx(); } });
$('#cvMx').addEventListener('mouseleave', ()=>{ mxHover=null; renderMx(); });
/* ================= 场景剧本：任务驱动的一键状态编排 ================= */
function setLens(l){ S.lens=l;
  $$('.lensbtn').forEach(x=>x.classList.toggle('on', x.dataset.lens===l)); updateSlices(); }
function setRel(r){ S.rel=r;
  $$('.relbtn').forEach(x=>x.classList.toggle('on', x.dataset.rel===r)); invalidateRel(); }
function setPlay(on){ S.playing=on;
  $('#btnPlay').textContent = on?'⏸ 暂停':'▶ 播放';
  $('#btnPlay').classList.toggle('on', on); }
function scenario(k){
  S.selLayer=null; S.selCard=null; renderMemPanel(); describeModelSel();
  setTab('hier');
  if(k==='patrol' || k==='reset'){                 // 巡检：健康度热力 + 整 Pod 俯视 + 播放
    S.filterHost=null; setLens('NONE'); setRel('AUTO');
    S.focusPod=0; renderPodRows(); closeDrawer();
    S.wire='AUTO'; $$('.wirebtn').forEach(x=>x.classList.toggle('on', x.dataset.wire==='AUTO'));
    if(S.anomaly && k==='reset') $('#btnAnom').onclick();
    formTarget='phys'; formBtns();
    if(k==='reset'){ setPlay(false); S.t=0; yaw=.82; pitch=.58; zoomBias=1; }
    else setPlay(true);
    setLevel('L4');
  }
  if(k==='moe'){                                   // 告警定位：EP 透镜 + 下钻越界专家 + 泳道抓拍
    if(!S.anomaly) $('#btnAnom').onclick();
    setLens('EP'); setRel('EP');
    S.filterHost = expertHosts[anomExperts[0]]; invalidateRel();
    S.focusHost = S.filterHost; S.focusChip = S.filterHost*8;
    formTarget='phys'; formBtns();
    S.t=.62; setPlay(false); syncPhase();
    setLevel('L4'); openDrawer('lane');
  }
  if(k==='slowdp'){                                // 找慢副本：魔方 DP 平铺 + DP 阶段
    S.filterHost=null; setLens('DP'); setRel('DP'); closeDrawer();
    formTarget='cube'; formBtns();
    if(cubeMode!==1){ cubePrev=cubeMode; cubeMode=1; cubeBlend=0;
      [0,1,2,3,4].forEach(i=>$('#cm'+i).classList.toggle('on', i===1)); }
    S.t=.9; setPlay(true); syncPhase();
  }
  if(k==='deep'){                                  // 单机深潜：当前焦点 Host 下钻 + 泳道
    S.filterHost=S.focusHost; setRel('TP'); invalidateRel();
    formTarget='phys'; formBtns(); setLevel('L2'); openDrawer('lane');
  }
  if(k==='deploy'){                                // 部署审视：任务透镜
    S.filterHost=null; setLens('JOB'); closeDrawer();
    formTarget='phys'; formBtns(); setLevel('L4');
  }
  renderFilterBar(); updateCounts(); touchLeft(); renderViewlab();
}
[['scPatrol','patrol'],['scMoe','moe'],['scSlow','slowdp'],['scDeep','deep'],
 ['scDeploy','deploy'],['scReset','reset']].forEach(p=>{
  const el=$('#'+p[0]); if(el) el.onclick=()=>scenario(p[1]); });
/* ---- 全局标量迷你曲线（v2 组件〇：Loss / LR / MFU · LossScale 溢出红点） ---- */
const sparkCv = $('#sparks'), sg = sparkCv ? sparkCv.getContext('2d') : null;
const SD = { loss:[], lr:[], mfu:[], dots:[31], n:64, t:0, lastTick:-1 };
for(let i=0;i<SD.n;i++){ SD.loss.push(6*Math.exp(-i/22)+2.6+Math.sin(i*1.7)*.15);
  SD.lr.push(i<10? i/10*3 : 3*Math.pow(.985,i-10));
  SD.mfu.push(52+Math.sin(i/6)*3); }
function stepSparks(){ SD.t++;
  SD.loss.push(Math.max(2.2, SD.loss[SD.loss.length-1]*.999+(Math.random()-.5)*.1)); SD.loss.shift();
  SD.lr.push(SD.lr[SD.lr.length-1]*.999); SD.lr.shift();
  SD.mfu.push(52+Math.sin(SD.t/6)*3+(S.anomaly?-9:0)+Math.random()); SD.mfu.shift();
  SD.dots = SD.dots.map(d=>d-1).filter(d=>d>2);
  if(S.anomaly && SD.t%24===0) SD.dots.push(SD.n-2);
  renderSparks(); }
function renderSparks(){ if(!sg) return;
  sg.clearRect(0,0,340,36);
  const draw=(pts,x0,color,name,dots)=>{ const w=100,h=24,y0=9;
    const mn=Math.min(...pts), mx=Math.max(...pts);
    sg.strokeStyle=color; sg.lineWidth=1.2; sg.beginPath();
    pts.forEach((v,i)=>{ const x=x0+i*w/(pts.length-1), y=y0+h-(v-mn)/(mx-mn||1)*h;
      i?sg.lineTo(x,y):sg.moveTo(x,y); });
    sg.stroke();
    (dots||[]).forEach(d=>{ if(d<0||d>=pts.length) return;
      const x=x0+d*w/(pts.length-1), y=y0+h-(pts[d]-mn)/(mx-mn||1)*h;
      sg.fillStyle='#f85149'; sg.beginPath(); sg.arc(x,y,2.5,0,7); sg.fill(); });
    sg.fillStyle='#6e7681'; sg.font='9px sans-serif'; sg.textAlign='left'; sg.fillText(name,x0,7); };
  draw(SD.loss,2,'#f85149','Loss · Scale溢出=红点',SD.dots);
  draw(SD.lr,118,'#d29922','LR');
  draw(SD.mfu,234,'#3fb950','MFU'+(S.anomaly?' ↓':''));
}
/* ---- 尺寸 / 主循环 ---- */
function resize(){ const r = right.getBoundingClientRect();
  W = r.width; H = r.height;
  renderer.setSize(W,H,false);
  camera.aspect = W/H; camera.updateProjectionMatrix(); }
window.addEventListener('resize', ()=>{ resize(); drawArcs();
  try{ if(drawer.classList.contains('show')) syncDrawer(); }catch(e){} });
let last = performance.now();
function loop(now){
  const dt = Math.min(.1,(now-last)/1000); last = now;
  if(S.playing){ S.t = (S.t + dt/16) % 1; syncPhase();
    if(S.tab==='model') renderMM();
    const tick = (S.t*48)|0;
    if(tick!==SD.lastTick){ SD.lastTick=tick; stepSparks(); }
    try{ if(drawer.classList.contains('show') && drawerTab==='lane') renderLane(); }catch(e){} }
  { let moving=false;
    ['phys','cube','stack'].forEach(fm=>{ const tgt = formTarget===fm?1:0, d = tgt-Wgt[fm];
      if(Math.abs(d)>0.001){ Wgt[fm]+=Math.sign(d)*Math.min(dt/0.9,Math.abs(d)); moving=true; }
      else Wgt[fm]=tgt; });
    if(moving){ S.morph=Wgt.cube; morphDirty=true; } }
  if(cubeBlend<1){ cubeBlend=Math.min(1,cubeBlend+dt/0.8); morphDirty=true; }
  if(morphDirty){ applyMorph(); morphDirty=false; }
  if(commDirty){ buildComm(); commDirty=false; }
  if(colorsDirty){ applyColors(true); colorsDirty=false; }
  else if(S.playing) applyColors(false);
  updateIndicators(); updateCommPulse(now); updateCamera(dt);
  renderer.render(scene, camera);
  requestAnimationFrame(loop);
}
/* ---- 初始化 ---- */
resize();
applyMorph(); applyColors(true); buildComm(); updateSlices();
setLevel('L4'); formBtns(); syncPhase();
renderL3(); renderL2(); renderL4(); renderChipZoom(); renderProbe(); renderHUD(); renderSparks(); renderPodRows(); updateLevelKPI(); renderTopN();
describeModelSel(); renderMM(); renderFilterBar(); updateCounts();
{ const g = camGoal(); camCur.t.copy(g.t); camCur.d = g.d; }
requestAnimationFrame(drawArcs);
requestAnimationFrame(loop);
</script>
