function buildPhysLines(dim){
  const fh=S.focusHost, dpF=dpOf(fh), ppF=ppOf(fh);
  if(dim==='TP'){
    hostPos(fh,vA);
    const ring=[]; for(let k=0;k<=24;k++){ const a=k/24*Math.PI*2;
      ring.push(V3(vA.x+Math.cos(a)*.62, vA.y+.16, vA.z+Math.sin(a)*.52)); }
    commLine(ring, 0x39c5cf, .95);
    for(let i=0;i<26;i++){ const cab=(i*37)%128, x=(cab%16-7.5)*1.8, z=((cab>>4)-3.5)*2.4;
      commLine([V3(x,.35,z),V3(x,3.35,z)], 0x39c5cf, .3); } }
  if(dim==='PP'){
    const pts=[]; for(let k=0;k<16;k++) pts.push(hostPos(dpF*16+k,new THREE.Vector3()).add(V3(0,.12,0)));
    commLine(pts, 0xd29922, .9);
    commLine(bez(pts[0].clone(),pts[15].clone(),2.2), 0xd29922, .35); }
  if(dim==='EP'){
    const hub0 = expertHosts[5];
    const hub = hostPos(hub0,new THREE.Vector3()).add(V3(0,.15,0));
    for(let e=1;e<N_EXP;e+=5){ const h2=expertHosts[e]; if(h2===hub0) continue;
      commLine(bez(hub.clone(), hostPos(h2,new THREE.Vector3()).add(V3(0,.15,0)), 2.5+((h2*13)%30)/10), 0xa371f7, .55); }
    if(S.anomaly){ const p1=podXZ(1);
      if(!S.scatter){        // 未散射：4 条环共用同一跨域出口 → 单链路 4× 带宽需求（NCCL 无散射反例）
        const exit = hostPos(expertHosts[anomExperts[0]], new THREE.Vector3());
        for(let k=1;k<4;k++){ const h2=expertHosts[anomExperts[k*2]];
          commLine(bez(hostPos(h2,new THREE.Vector3()), exit.clone().add(V3(0,.6,0)), 1.4), 0xf85149, .6); }
        commLine(bez(exit.clone(), V3(p1.x, 6.8, p1.z), 10), 0xf85149, 1); }
      else {                 // 散射（SCATTER_XDC 语义）：每条环独立跨域出口 → 单链路峰值 ↓75%
        for(let k=0;k<4;k++){ const h2=expertHosts[anomExperts[k*2]];
          commLine(bez(hostPos(h2,new THREE.Vector3()), V3(p1.x+(k-1.5)*5, 6.8, p1.z), 9), 0xd29922, .8); } } } }
  if(dim==='DP'){
    const pts=[]; for(let d=0;d<64;d+=8) pts.push(hostPos(d*16+ppF,new THREE.Vector3()));
    for(let k=0;k<pts.length;k++){
      const a2=pts[k].clone().add(V3(0,.1,0)), b2=pts[(k+1)%pts.length].clone().add(V3(0,.1,0));
      commLine(bez(a2,b2,3.2), 0x58a6ff, .6);                                  // Channel 0
      commLine(bez(a2.clone().add(V3(0,.4,0)), b2.clone().add(V3(0,.4,0)), 3.2), 0x58a6ff, .28); } // Channel 1
    const p2=podXZ(2);
    commLine(bez(pts[0].clone(), V3(p2.x,6.8,p2.z), 10), 0x58a6ff, .35); }
}
function buildPathLines(){        // 消息路径诊断（NCCL 2.12 PXN：跨轨 3-hop → 挪轨 1-hop）
  const srcH = S.focusHost, dstH = (srcH+517)%N_HOST;
  const a = hostPos(srcH,new THREE.Vector3()), b = hostPos(dstH,new THREE.Vector3());
  const dot3 = (p,col,rr)=>{ const s=new THREE.Mesh(new THREE.SphereGeometry(rr||.26,10,10),
      new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:.9}));
    s.material.userData.base=.9; s.position.copy(p); commGroup.add(s); };
  const tag = (txt,col,w2,p)=>{ const l=makeLabel(txt,col,w2);
    l.material.userData.base=1; l.position.copy(p); commGroup.add(l); };
  // 路径①：跨轨 3-hop（NIC→Leaf→Spine→Leaf→NIC）
  const spine = V3(0, 9.6, 0);
  const leafA = V3(a.x*.72, 5.6, a.z*.72), leafB = V3(b.x*.72, 5.6, b.z*.72);
  [[a,leafA],[leafA,spine],[spine,leafB],[leafB,b]].forEach(sg=>
    commLine(bez(sg[0].clone(), sg[1].clone(), .7), 0xf85149, .75));
  [leafA,spine,leafB].forEach(p=>dot3(p,0xf85149));
  tag('跨轨 3-hop：NIC→Leaf→Spine→Leaf→NIC（穿越二层脊交换机）','#f85149',20, V3(0,11.2,0));
  // 路径②：PXN 1-hop（NVLink 挪到同轨 GPU → 本地 NIC 直达，支持 8 消息聚合）
  const mid = hostPos(srcH^1, new THREE.Vector3());
  commLine(bez(a.clone(), mid.clone(), .5), 0x3fb950, .95);
  commLine(bez(mid.clone(), b.clone(), 2.4), 0x3fb950, .95);
  dot3(mid, 0x3fb950, .22);
  tag('PXN 1-hop：NVLink/UB 挪轨 → 同轨 NIC 直达 · 支持消息聚合','#3fb950',18,
      V3((a.x+b.x)/2, 3.8, (a.z+b.z)/2));
  tag(`Host ${srcH} → Host ${dstH}`,'#e6edf3',8, V3(a.x, a.y+1.3, a.z));
}
function buildFlowLines(){                    // 互联流量：主干链路 颜色/亮度=占用（绿→橙→红）
  for(let i=0;i<30;i++){ const cab=(i*19)%128, x=(cab%16-7.5)*1.8, z=((cab>>4)-3.5)*2.4;
    const side = cab%2? 15.4 : -15.4;
    const load = .2 + rng(cab*3+S.phase*7)*.8;
    const col = load>.85? 0xf85149 : load>.55? 0xd29922 : 0x3fb950;
    commLine(bez(V3(x,3.4,z), V3(side,1.4,z*.4), 1.6), col, .3+load*.6); }
  if(S.anomaly){ const p1=podXZ(1);
    commLine(bez(V3(15.4,1.5,0), V3(p1.x-16,6,p1.z), 8), 0xf85149, .95); }
}
function buildLinkLines(){                    // 物理链路健康：绿=正常 橙=降级 红=中断（带缺口）
  for(let i=0;i<32;i++){ const cab=(i*11)%128, x=(cab%16-7.5)*1.8, z=((cab>>4)-3.5)*2.4;
    const side = i<16? -15.4 : 15.4;
    const st = cab===41? 2 : (cab%13===0? 1 : 0);
    const col = st===2? 0xf85149 : st===1? 0xd29922 : 0x2ea043;
    if(st===2){
      commLine([V3(x,2.2,z), V3(x+(side-x)*.4, 1.9, z*.72)], col, .95);
      commLine([V3(x+(side-x)*.6, 1.7, z*.55), V3(side,1.4,z*.4)], col, .95); }
    else commLine([V3(x,2.2,z), V3(side,1.4,z*.4)], col, st===1? .85 : .28); }
}

