/* ================= v20 连线镜头公共设施 =================
   原则（源自浅色 2D 版）：① 统一状态色 绿<40% 黄40-70% 红>70%；
   ② 连线按选区层级聚合（L5 以上 → Pod↔Pod 粗流）；③ 宽度=占用量；
   ④ 方向粒子=流向；⑤ 每束流挂语义标签（算子/介质/量），软硬同框 */
const stateHex = v => v>.7? 0xf85149 : v>.4? 0xd29922 : 0x3fb950;
const stateCss = v => v>.7? '#f85149' : v>.4? '#d29922' : '#3fb950';
function flowTube(pts, color, load, base, medium){       // 粗管：半径=负载
  const curve = new THREE.CatmullRomCurve3(pts);
  const g = new THREE.TubeGeometry(curve, Math.max(8,Math.min(64,pts.length*3)), .05+(load||0)*.16, 5, false);
  const m = new THREE.MeshBasicMaterial({color, transparent:true, opacity:base, depthWrite:false});
  m.userData.base = base; m.userData.medium = medium||null;
  const mesh = new THREE.Mesh(g,m); commGroup.add(mesh); return mesh;
}
let movers = [];
function clearMovers(){ movers.length = 0; }             // 网格随 commGroup 一并销毁
function addMover(pts, color, speed, size, medium){      // 方向粒子：沿线移动=流向
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(size||.13,8,8),
    new THREE.MeshBasicMaterial({color, transparent:true, opacity:.95, depthWrite:false}));
  mesh.material.userData.base = .95; mesh.material.userData.medium = medium||null;
  mesh.material.userData.noPulse = true;
  commGroup.add(mesh);
  movers.push({pts, mesh, speed:speed||.5, off:rng(movers.length*7.7)});
}
function tickMovers(now){
  const t0 = now/1000;
  for(const mv of movers){
    const f = (t0*mv.speed + mv.off)%1, n = mv.pts.length-1;
    const i = Math.min(n-1, (f*n)|0), k = f*n-i;
    mv.mesh.position.lerpVectors(mv.pts[i], mv.pts[i+1], k);
  }
}
function wireLab(text, color, w, pos){                   // 语义标签（不随脉冲闪烁）
  const l = makeLabel(text, color, w);
  l.material.userData.base = 1; l.material.userData.noPulse = true;
  l.position.copy(pos); commGroup.add(l); return l;
}
function dotAt(p, color, r){
  const s = new THREE.Mesh(new THREE.SphereGeometry(r||.2,10,10),
    new THREE.MeshBasicMaterial({color, transparent:true, opacity:.9, depthWrite:false}));
  s.material.userData.base = .9; s.position.copy(p); commGroup.add(s); return s;
}
const aggPod = ()=> S.level==='L7'||S.level==='L6'||S.level==='L5';
/* 通信单元（矩阵行列）：64 单元 × 16 Host（=2 柜） */
const N_UNIT = 64;
function unitPos(u,out){ out = hostPos(u*16+8, out); out.y = 1.3; return out; }
function mxVal(i,j){                                     // 单元 i⇄j 占用（随阶段/异常联动）
  if(i===j) return 0;
  const ph = PHASES[S.phase].id;
  let v = .08 + .2*rng(i*64+j+S.phase*11);
  const d = Math.abs(i-j);
  if(ph==='TP') v += .8*Math.exp(-d*d/3);                // 近对角软带：柜内/邻柜 UB
  if(ph==='PP') v += (d===1?.62:0) + .28*Math.exp(-d*d/8);
  if(ph==='EP'){ const hubU=(expertHosts[5]/16)|0;
    if(i===hubU||j===hubU) v+=.55;
    if(isExpertHost[i*16+5]||isExpertHost[j*16+5]) v+=.22;
    if(rng(i*7+j*13)>.78) v+=.2; }                       // 散点浪涌纹理
  if(ph==='DP'){ if((i%4)===(j%4)) v+=.5; }              // 同位副本条纹
  if(S.anomaly && ph==='EP' && (i===63||j===63)) v+=.45; // 跨 Pod 出口单元打爆
  return Math.min(1,v);
}
function mediaStats(){                                   // 四介质占用（同浅色版四条）
  const ph = PHASES[S.phase].id;
  const b = { TP:[.67,.22,.12,.08], PP:[.49,.38,.15,.09],
              EP:[.62,.49,.21,.12], DP:[.41,.35,.52,.17] }[ph].slice();
  if(S.anomaly && ph==='EP'){ b[1]=Math.min(1,b[1]+.3); b[2]=Math.min(1,b[2]+.25); }
  return [ ['UB','UB · 节点/柜间',b[0]], ['RDMA','RDMA · 参数面',b[1]],
           ['DP','集群 DP AllReduce',b[2]], ['VPC','VPC · 管理面',b[3]] ];
}
function buildPodAgg(dim){        // 选区在 Pod 之上 → 聚合为 Pod↔Pod 粗流（回答"在哪"）
  const o=V3(0,4,0);
  const n = dim==='DP'?9 : dim==='EP'?7 : 5;
  for(let k=1;k<=n;k++){ const p=podXZ((k*7)%63+1);
    const load=.25+rng(k*31+S.phase*7)*.65;
    const pts=bez(o.clone(),V3(p.x,4,p.z),12+k);
    flowTube(pts, stateHex(load), load, .75, dim==='DP'?'DP':'RDMA');
    addMover(pts, 0xffffff, .3+load*.3, .16);
  }
  wireLab(`选区 ${S.level} · Pod↔Pod 聚合流 · 颜色=状态 宽度=占用 · 下钻 L4 展开柜级`, '#8b949e', 30, V3(0,14,0));
}
/* ======== 镜头① 自动·随阶段：当前算子 = 聚合流带 + 方向粒子 + 语义标签 ======== */
function buildPhaseLines(dim){
  if(aggPod()){ buildPodAgg(dim); return; }
  const fh=S.focusHost, dpF=dpOf(fh), ppF=ppOf(fh);
  if(dim==='TP'){
    hostPos(fh,vA);
    const ring=[]; for(let k=0;k<=24;k++){ const a=k/24*Math.PI*2;
      ring.push(V3(vA.x+Math.cos(a)*.62, vA.y+.16, vA.z+Math.sin(a)*.52)); }
    flowTube(ring, 0x39c5cf, .5, .95, 'UB');
    addMover(ring, 0xffffff, .55, .1, 'UB');
    wireLab(`TP·AllReduce ×8 rank · Host ${fh} · 节点内 UB`, '#7ee0e8', 13, V3(vA.x,vA.y+2.2,vA.z));
    wireLab('全 Pod 1024 台同构发生（示焦点 1 台）', '#8b949e', 11, V3(vA.x,vA.y+1.5,vA.z));
  }
  if(dim==='PP'){
    const pts=[]; for(let k=0;k<16;k++) pts.push(hostPos(dpF*16+k,new THREE.Vector3()).add(V3(0,.14,0)));
    flowTube(pts, 0xd29922, .4, .9, 'UB');
    addMover(pts, 0xffffff, .22, .12, 'UB'); addMover(pts, 0xffe08a, .22, .1, 'UB');
    dotAt(pts[0],0xffffff,.16); dotAt(pts[15],0xffffff,.16);
    wireLab('S0·L1-3','#ffe08a',6,pts[0].clone().add(V3(0,.9,0)));
    wireLab('S15·L46-48','#ffe08a',7,pts[15].clone().add(V3(0,.9,0)));
    for(let k=4;k<15;k+=5) wireLab('S'+k,'#d29922',3.5,pts[k].clone().add(V3(0,.6,0)));
    flowTube(bez(pts[15].clone(),pts[0].clone(),2.4), 0xd29922, .08, .3, 'UB');
    wireLab(`PP·接力 Send/Recv · DP副本${dpF} · 16 段=整网48层 · 粒子=激活流向`, '#ffd28a', 17, pts[7].clone().add(V3(0,2.8,0)));
  }
  if(dim==='EP'){
    const hub0=expertHosts[5];
    const hub=hostPos(hub0,new THREE.Vector3()).add(V3(0,.15,0));
    const byCab=new Map();
    for(let e=0;e<N_EXP;e++){ const h2=expertHosts[e]; if(h2===hub0) continue;
      const cb=cabOf(h2); if(!byCab.has(cb)) byCab.set(cb,[]); byCab.get(cb).push(e); }
    let i=0;
    byCab.forEach((es,cb)=>{ if(i++%2) return;           // 按柜聚合 + 采样，避免糊成毛线球
      const p=hostPos(expertHosts[es[0]],new THREE.Vector3()).add(V3(0,.15,0));
      const load=Math.min(.9,.3+es.length*.15+rng(cb)*.2);
      const pts=bez(hub.clone(),p,1.6+((cb*13)%30)/12);
      flowTube(pts,0xa371f7,load*.6,.5,'UB');
      addMover(pts,0xd2a8ff,.45+rng(cb)*.4,.09,'UB');
      addMover(pts.slice().reverse(),0xd2a8ff,.45,.07,'UB');   // AllToAll 双向
    });
    dotAt(hub,0xe3b341,.3);
    wireLab(`EP·AllToAll · 热点专家 Host ${hub0} ⇄ 63 专家（按柜聚合）· 粒子双向=浪涌`,'#d2a8ff',18,hub.clone().add(V3(0,3,0)));
    if(S.anomaly){ const p1=podXZ(1);
      if(!S.scatter){
        const exit=hostPos(expertHosts[anomExperts[0]],new THREE.Vector3());
        for(let k2=1;k2<4;k2++){ const h2=expertHosts[anomExperts[k2*2]];
          flowTube(bez(hostPos(h2,new THREE.Vector3()),exit.clone().add(V3(0,.6,0)),1.4),0xf85149,.4,.6,'RDMA'); }
        const cr=bez(exit.clone(),V3(p1.x,6.8,p1.z),10);
        flowTube(cr,0xf85149,.95,.95,'RDMA'); addMover(cr,0xffffff,.65,.15,'RDMA');
        wireLab('⚠ 8 专家越界→SN1 · 4 条环共用单出口 = 单链路 4× 带宽','#ffa198',20,V3(p1.x*.5,9.5,p1.z*.5));
      } else {
        for(let k2=0;k2<4;k2++){ const h2=expertHosts[anomExperts[k2*2]];
          const cr=bez(hostPos(h2,new THREE.Vector3()),V3(p1.x+(k2-1.5)*5,6.8,p1.z),9);
          flowTube(cr,0xd29922,.4,.8,'RDMA'); addMover(cr,0xffe08a,.55,.1,'RDMA'); }
        wireLab('已散射 SCATTER_XDC：4 环独立出口 · 单链路峰值 ↓75%','#7ee787',20,V3(p1.x*.5,9.5,p1.z*.5));
      } }
  }
  if(dim==='DP'){
    const pts=[]; for(let d=0;d<64;d+=8) pts.push(hostPos(d*16+ppF,new THREE.Vector3()));
    for(let k=0;k<pts.length;k++){
      const a2=pts[k].clone().add(V3(0,.1,0)), b2=pts[(k+1)%pts.length].clone().add(V3(0,.1,0));
      const seg=bez(a2,b2,3.2);
      flowTube(seg,0x58a6ff,.45,.6,'DP'); addMover(seg,0x9ecbff,.4,.1,'DP');
      flowTube(bez(a2.clone().add(V3(0,.5,0)),b2.clone().add(V3(0,.5,0)),3.2),0x58a6ff,.15,.25,'DP'); }
    pts.forEach(p=>dotAt(p.clone().add(V3(0,.15,0)),0x58a6ff,.13));
    wireLab(`DP·梯度 AllReduce · Stage${ppF} 环（示 8/64 副本）· 双股=2 Channels`,'#9ecbff',17,V3(0,6.6,0));
    const p2=podXZ(2), cr=bez(pts[0].clone(),V3(p2.x,6.8,p2.z),10);
    flowTube(cr,0x58a6ff,.25,.4,'DP');
    wireLab('跨超节点 DP 同步（多 Pod 作业）→ SN2','#9ecbff',13,V3(p2.x*.55,8.8,p2.z*.55));
  }
}
/* ======== 镜头② 通信域：域轮廓 + 成员标记（谁属于一个通信组，一眼可见） ======== */
function buildDomainLines(dim){
  const fh=S.focusHost, dpF=dpOf(fh), ppF=ppOf(fh);
  if(dim==='TP'){
    const cab=cabOf(fh);
    for(let s=0;s<8;s++){ const h=cab*8+s; hostPos(h,vA);
      const ring=[]; for(let k=0;k<=20;k++){ const a=k/20*Math.PI*2;
        ring.push(V3(vA.x+Math.cos(a)*.68, vA.y+.1, vA.z+Math.sin(a)*.56)); }
      flowTube(ring,0x39c5cf,.1,h===fh?.9:.4,'UB'); }
    hostPos(fh,vA);
    wireLab(`TP 通信域 = 1 台 Host（8×NPU）· 全 Pod 1024 个域 · 示焦点柜${cab} 的 8 个`,'#7ee0e8',19,V3(vA.x,vA.y+2.5,vA.z));
  }
  if(dim==='PP'){
    [0,8,16,24].forEach((off,i)=>{ const d=(dpF+off)%64, pts=[];
