function addMover(pts, color, speed, size, medium){      // 方向粒子：沿线移动=流向
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(size||.13,8,8),
    new THREE.MeshBasicMaterial({color, transparent:true, opacity:.95, depthWrite:false}));
  mesh.material.userData.base = .95; mesh.material.userData.medium = medium||null;
  mesh.material.userData.noPulse = true;
