  wireLab('跨轨 3-hop：NIC→Leaf→Spine→Leaf→NIC ≈3.2μs · 穿越二层脊交换','#f85149',21,V3(0,11.6,0));
  const mid=hostPos(srcH^1,new THREE.Vector3());
