/* ======== 互联矩阵叠加卡：浅色 2D 版 Host×Host 的 3D 联动版 ======== */
const mxcv = $('#mxcv'), gmx = mxcv.getContext('2d');
const mxHiGroup = new THREE.Group(); scene.add(mxHiGroup);
function syncMxCard(){
  $('#mxcard').classList.toggle('show', S.mxShow);
  $('#btnMx').classList.toggle('on', S.mxShow);
  if(S.mxShow) renderMxCard();
}
function renderMxCard(){
  if(!S.mxShow) return;
  $('#mxmedia').innerHTML = mediaStats().map(([k,lab,v])=>
    `<div class="mrow${S.mxMedium===k?' sel':''}" data-med="${k}">
       <span class="ml">${lab}</span>
       <span class="mb"><i style="width:${(v*100)|0}%;background:${stateCss(v)}"></i></span>
       <span class="mv">${(v*100)|0}%</span></div>`).join('');
  const cs=232/N_UNIT;
  gmx.clearRect(0,0,232,232);
  for(let i=0;i<N_UNIT;i++) for(let j=0;j<N_UNIT;j++){
    const v=mxVal(i,j);
    gmx.fillStyle = i===j? '#0d1117' : stateCss(v);
    gmx.globalAlpha = i===j? 1 : .25+v*.75;
    gmx.fillRect(j*cs,i*cs,cs-.3,cs-.3); }
  gmx.globalAlpha=1;
  const box=(pr,col)=>{ if(!pr) return; gmx.strokeStyle=col; gmx.lineWidth=1.2;
    gmx.strokeRect(pr[1]*cs-1,pr[0]*cs-1,cs+2,cs+2);
    gmx.strokeRect(pr[0]*cs-1,pr[1]*cs-1,cs+2,cs+2); };   // 对称格一起框
  box(S.mxPin,'#58a6ff'); box(S.mxHover,'#ffffff');
  const pr = S.mxHover||S.mxPin;
  $('#mxinfo').innerHTML = pr
    ? `单元 <b>${pr[0]}</b>（Host ${pr[0]*16}-${pr[0]*16+15}·柜${pr[0]*2}-${pr[0]*2+1}）⇄ 单元 <b>${pr[1]}</b> · 占用 <b style="color:${stateCss(mxVal(pr[0],pr[1]))}">${(mxVal(pr[0],pr[1])*100)|0}%</b><br>3D 已点亮此对 · ${S.mxPin&&!S.mxHover?'已钉住（再点取消）':'点击钉住'}`
    : '行/列 = 64 通信单元（1 单元=16 Host=2 柜）· 色=状态 · 悬停格→3D 点亮该对 · 点介质条→过滤 3D 流量';
}
function renderMxHi(){                                    // 矩阵 → 3D 交叉高亮
  for(let i=mxHiGroup.children.length-1;i>=0;i--){ const o=mxHiGroup.children[i];
    if(o.geometry) o.geometry.dispose();
    if(o.material){ if(o.material.map) o.material.map.dispose(); o.material.dispose(); }
    mxHiGroup.remove(o); }
  const pr = S.mxHover||S.mxPin; if(!pr||!S.mxShow) return;
  const a=unitPos(pr[0],new THREE.Vector3()), b=unitPos(pr[1],new THREE.Vector3());
  const v=mxVal(pr[0],pr[1]);
  const tube=new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(bez(a,b,2.6)),24,.09+v*.15,5,false),
    new THREE.MeshBasicMaterial({color:stateHex(v),transparent:true,opacity:.95,depthWrite:false}));
  mxHiGroup.add(tube);
  [a,b].forEach(p=>{ const m=new THREE.Mesh(new THREE.SphereGeometry(.26,10,10),
    new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.9}));
    m.position.copy(p); mxHiGroup.add(m); });
  const l=makeLabel(`单元${pr[0]} ⇄ 单元${pr[1]} · ${(v*100)|0}%`, stateCss(v), 10);
  l.position.copy(a.clone().add(b).multiplyScalar(.5).add(V3(0,2.4,0))); mxHiGroup.add(l);
}
$('#btnMx').onclick = ()=>{ S.mxShow=!S.mxShow; syncMxCard(); renderMxHi(); };
$('#mxClose').onclick = ()=>{ S.mxShow=false; syncMxCard(); renderMxHi(); };
$('#mxmedia').addEventListener('click', ev=>{ const r=ev.target.closest('.mrow'); if(!r) return;
  S.mxMedium = S.mxMedium===r.dataset.med? null : r.dataset.med;
  renderMxCard(); commDirty=true; });
mxcv.addEventListener('mousemove', ev=>{ const r=mxcv.getBoundingClientRect();
  const j=Math.min(63,Math.max(0,((ev.clientX-r.left)/r.width*64)|0));
  const i=Math.min(63,Math.max(0,((ev.clientY-r.top)/r.height*64)|0));
  const nh = i===j? null : [i,j];
  if(JSON.stringify(nh)!==JSON.stringify(S.mxHover)){ S.mxHover=nh; renderMxCard(); renderMxHi(); } });
mxcv.addEventListener('mouseleave', ()=>{ S.mxHover=null; renderMxCard(); renderMxHi(); });
mxcv.addEventListener('click', ()=>{ if(!S.mxHover) return;
  S.mxPin = (S.mxPin&&S.mxPin[0]===S.mxHover[0]&&S.mxPin[1]===S.mxHover[1])? null : S.mxHover.slice();
  renderMxCard(); renderMxHi(); });

