// Minimal THREE r128 stub — enough to execute app logic (no real rendering)
class Vector3 {
  constructor(x=0,y=0,z=0){ this.x=x;this.y=y;this.z=z; }
  set(x,y,z){ this.x=x;this.y=y;this.z=z; return this; }
  setY(y){ this.y=y; return this; }
  clone(){ return new Vector3(this.x,this.y,this.z); }
  copy(v){ this.x=v.x;this.y=v.y;this.z=v.z; return this; }
  add(v){ this.x+=v.x;this.y+=v.y;this.z+=v.z; return this; }
  multiplyScalar(s){ this.x*=s;this.y*=s;this.z*=s; return this; }
  addScaledVector(v,s){ this.x+=v.x*s;this.y+=v.y*s;this.z+=v.z*s; return this; }
  lerp(v,k){ this.x+=(v.x-this.x)*k;this.y+=(v.y-this.y)*k;this.z+=(v.z-this.z)*k; return this; }
  lerpVectors(a,b,k){ this.x=a.x+(b.x-a.x)*k;this.y=a.y+(b.y-a.y)*k;this.z=a.z+(b.z-a.z)*k; return this; }
}
class Vector2 { constructor(x=0,y=0){this.x=x;this.y=y;} set(x,y){this.x=x;this.y=y;return this;} }
class Color {
  constructor(c){ this.r=1;this.g=1;this.b=1; if(c!=null) this.set(c); }
  set(c){ return this; } setStyle(s){ if(typeof s!=='string') throw new Error('setStyle non-string: '+s); return this; }
  lerp(){ return this; }
}
class Object3D {
  constructor(){ this.position=new Vector3(); this.rotation={set(){}}; this.scale=new Vector3(1,1,1);
    this.scale.set=function(x,y,z){this.x=x;this.y=y;this.z=z;return this;};
    this.children=[]; this.visible=true; this.matrix={}; this.userData={}; }
  add(...o){ o.forEach(c=>this.children.push(c)); return this; }
  remove(o){ const i=this.children.indexOf(o); if(i>=0) this.children.splice(i,1); return this; }
  traverse(fn){ fn(this); this.children.forEach(c=>c.traverse?c.traverse(fn):fn(c)); }
  updateMatrix(){}
  lookAt(){}
}
class Group extends Object3D {}
class Scene extends Object3D {}
class BufferAttribute { constructor(arr,sz){ this.array=arr; this.itemSize=sz; this.needsUpdate=false; }
  setXYZ(){ } }
class BufferGeometry {
  constructor(){ this.attributes={ position:new BufferAttribute(new Float32Array(24),3) }; }
  setFromPoints(pts){ this.attributes.position=new BufferAttribute(new Float32Array(pts.length*3),3);
    this.attributes.position.setXYZ=function(){}; return this; }
  setAttribute(n,a){ this.attributes[n]=a; return this; }
  rotateX(){ return this; } rotateY(){ return this; }
  dispose(){}
}
class BoxGeometry extends BufferGeometry {}
class SphereGeometry extends BufferGeometry {}
class PlaneGeometry extends BufferGeometry {}
