  constructor(){ super(); this.attributes.position=new BufferAttribute(new Float32Array(18),3); }
}
class TubeGeometry extends BufferGeometry { constructor(curve,seg,r,rad,closed){ super();
  if(!curve||typeof curve.getPoint!=='function') throw new Error('TubeGeometry: bad curve'); } }
class Material { constructor(o){ Object.assign(this,o||{}); this.userData={};
  if(this.color==null) this.color=new Color(); else if(!(this.color instanceof Color)) this.color=new Color(this.color); }
  dispose(){} }
class MeshBasicMaterial extends Material {}
class MeshLambertMaterial extends Material {}
class LineBasicMaterial extends Material {}
class SpriteMaterial extends Material {}
class Mesh extends Object3D { constructor(g,m){ super(); this.geometry=g; this.material=m; } }
class Line extends Mesh {} class LineSegments extends Mesh {}
class Sprite extends Object3D { constructor(m){ super(); this.material=m; } }
class InstancedMesh extends Mesh { constructor(g,m,n){ super(g,m); this.count=n; }
  setColorAt(i,c){ if(!this.instanceColor) this.instanceColor={needsUpdate:false}; }
  setMatrixAt(i,m){ if(!this.instanceMatrix) this.instanceMatrix={needsUpdate:false}; } }
class GridHelper extends Object3D { constructor(){ super(); this.material=new Material(); } }
class AmbientLight extends Object3D {} class DirectionalLight extends Object3D {}
class PerspectiveCamera extends Object3D { constructor(){ super(); this.aspect=1;this.near=.1;this.far=100; }
  updateProjectionMatrix(){} }
class Fog { constructor(){} }
class CanvasTexture { constructor(cv){ this.image=cv; } dispose(){} }
class QuadraticBezierCurve3 {
  constructor(a,m,b){ this.a=a;this.m=m;this.b=b; }
  getPoint(t){ const q=(p,q2,k)=>p+(q2-p)*k;
    const ax=q(this.a.x,this.m.x,t), ay=q(this.a.y,this.m.y,t), az=q(this.a.z,this.m.z,t);
    const bx=q(this.m.x,this.b.x,t), by=q(this.m.y,this.b.y,t), bz=q(this.m.z,this.b.z,t);
    return new Vector3(q(ax,bx,t),q(ay,by,t),q(az,bz,t)); }
  getPoints(n){ const out=[]; for(let i=0;i<=n;i++) out.push(this.getPoint(i/n)); return out; }
}
