/* ---- v20：按钮分组折叠（策略透镜 / 演练 / 连线镜头 / 形态 收成下拉组） ---- */
$$('.fold .foldhead').forEach(h=>h.addEventListener('click', ev=>{ ev.stopPropagation();
  const f=h.parentElement, was=f.classList.contains('open');
  $$('.fold').forEach(x=>x.classList.remove('open'));
  if(!was) f.classList.add('open'); }));
$$('.fold .fbody').forEach(bd=>bd.addEventListener('click', ev=>{
  if(ev.target.tagName==='BUTTON' && !ev.target.closest('#cubeModes'))
    setTimeout(()=>$$('.fold').forEach(x=>x.classList.remove('open')), 120); }));
document.addEventListener('click', ev=>{
  if(!ev.target.closest('.fold')) $$('.fold').forEach(x=>x.classList.remove('open')); });
function updateFoldHeads(){
  const lensName = {NONE:'无·健康度',TP:'TP×8',PP:'PP×16',DP:'DP×64',EP:'EP·MoE',SP:'SP·序列',CP:'CP·上下文',JOB:'任务·部署'}[S.lens]||S.lens;
  const wireName = {AUTO:'自动·随阶段',COMM:'通信域',FLOW:'互联流量',LINK:'物理链路',PATH:'消息路径·PXN'}[S.wire]||S.wire;
  const formName = {phys:'物理层级',cube:'逻辑魔方'+(cubeMode?(' · '+['','DP平铺','EP聚簇','TP切片','PP流水'][cubeMode]):''),stack:'层级堆叠'}[S.form]||S.form;
  const el=(id,html)=>{ const e=document.getElementById(id); if(e) e.innerHTML=html; };
  el('fhLens', `策略透镜 · <b>${lensName}</b> ▾`);
  el('fhWire', `连线镜头 · <b>${wireName}</b> ▾`);
  el('fhForm', `形态 · <b>${formName}</b> ▾`);
  const fs=document.getElementById('fhScen');
  if(fs){ fs.classList.toggle('on', S.anomaly);
    fs.innerHTML = S.anomaly? '演练 · <b style="color:#ffdcd7">EP 异常已注入</b> ▾' : '演练 ▾'; }
}

